        for (let type of bitTypes) { let ang = random(TWO_PI), spd = random(4, 9); this.bits.push({ type: type, x: 0, y: 0, vx: cos(ang)*spd, vy: sin(ang)*spd, rot: random(TWO_PI), vr: random(-0.4, 0.4), sz: random(8, 14), splat: false }); }
