        for (let i=0; i<6; i++) this.bits.push({ x:ox, y:oy, vx:random(-6,6), vy:random(-6,6), rot:random(TWO_PI), vr:random(-0.3,0.3), sz:random(4, 8), type: 'meat', splat: false });
