        fill(70, 76, 84);
        rect(0, 12 + gait * 2, 12, 10, 2);
        fill(88, 95, 104); rect(11, 13 + gait * 2, 20, 8, 2);
        fill(52, 57, 63);  rect(27, 12.5 + gait * 2, 8, 9, 2);
        fill(this.trimCol || color(255, 146, 40));
        rect(20, 14.5 + gait * 2, 3.5, 5, 1);

