    let lS = this.isMoving ? sin(this.walkCycle) * 12 * GP.swing : 0,
        bob = this.isMoving ? abs(sin(this.walkCycle)) * 2 * GP.bob + GP.lean : 0;
    if (this.mounted) { lS *= 0.35; bob *= 0.4; }
