function handleDesktop() {
  if (!player) return;
  
  let kDx = 0, kDy = 0;
  if (keyIsDown(65)) kDx -= 1; 
  if (keyIsDown(68)) kDx += 1; 
  if (keyIsDown(87)) kDy -= 1; 
  if (keyIsDown(83)) kDy += 1; 
  
  if (kDx !== 0 || kDy !== 0) {
      let mag = dist(0, 0, kDx, kDy);
      leftStick.active = true;
      leftStick.dx = kDx / mag;
      leftStick.dy = kDy / mag;
      window.isDesktop = true; 
  }
  if (keyIsDown(69) && meleeUnlocked) meleeInputHeld = true;

  // R to mount or step down. Edge-triggered: on a level trigger, holding the key
  // toggles sixty times a second and leaves you on or off the horse at random.
  const rDown = keyIsDown(82);
  if (rDown && !window.__rideKeyWas) {
      if (player.mounted) { player.dismount(); sfx.charge(); }
      else { const h = mountableHorse(); if (h) { player.mountHorse(h); sfx.charge(); } }
  }
  window.__rideKeyWas = rDown;


  if (window.isDesktop) {
      let worldMouseX = (mouseX / zoom) + camX;
      let worldMouseY = (mouseY / zoom) + camY;
      
      let aimDx = worldMouseX - player.x;
      let aimDy = worldMouseY - player.y;
      let aimMag = dist(0, 0, aimDx, aimDy);
      
      if (aimMag > 0) {
          rightStick.active = true;
          rightStick.dx = aimDx / aimMag;
          rightStick.dy = aimDy / aimMag;
          rightStick.dist = (mouseIsPressed && mouseButton === LEFT) ? 1.0 : 0.0;
      }
  }
}

function mousePressed() {
    if (touches.length === 0) touchStarted();
}

function drawSpeechBubble(x, y, txt) {
    push();
    
    // Check if Darchon is talking
    let isDarchon = txt.startsWith("[TABLET]");
    // Strip the "[TABLET]" tag out so it doesn't show in the actual bubble
    let displayText = isDarchon ? txt.replace("[TABLET] ", "") : txt;

    textFont('sans-serif'); textSize(14); textAlign(CENTER, CENTER); textLeading(18);
    let lines = displayText.split('\n');
    let maxW = 0;
    for (let l of lines) { let w = textWidth(l); if (w > maxW) maxW = w; }
    
    let h = lines.length * 18 + 20;
    let w = maxW + 30;
    let portraitSize = 0;

    // Expand the bubble width if Darchon is talking to fit the image
    if (isDarchon) {
        portraitSize = h; 
        w += portraitSize + 10; 
    }

    fill(255); stroke(0); strokeWeight(2);
    rect(x - w/2, y - h/2 - 10, w, h, 10);
    triangle(x, y + h/2 - 10, x - 10, y + h/2 - 10, x - 20, y + h/2 + 10); 

        // Draw and animate the portrait
    if (isDarchon && darchonFrames.length > 0 && darchonFrames[0] !== undefined) {
        let imgSize = portraitSize - 10;
        let imgX = x - w/2 + 5;
        let imgY = y - h/2 - 5;

        let currentFrame = darchonFrames[0]; // Default to idle

        if (typeof darchonTalkTimer !== 'undefined' && darchonTalkTimer > 0) {
            darchonTalkTimer--;
            
            // Cycle through frames 1, 2, and 3 every 5 frames
            let frameIndex = 1 + floor((frameCount % 15) / 5); 
            if (darchonFrames[frameIndex]) {
                currentFrame = darchonFrames[frameIndex];
            }
        }

        image(currentFrame, imgX, imgY, imgSize, imgSize);
    }


    fill(0); noStroke();
    // Shift text to the right so it doesn't overlap the image
    let textX = isDarchon ? x + (portraitSize / 2) : x;
    text(displayText, textX, y - 10);
    
    pop();
}

// --- NEW HELPER FUNCTIONS FOR CONTEXT PROMPTS ---
// The nearest animal the player could get on: alive, standing near enough to
// reach, and not currently running for its life.
// Cached: this is asked once a frame from the UI path just to decide whether to
// draw a button, and the answer cannot meaningfully change in a tenth of a
// second. The scan itself walks every live entity, which is a hundred and sixty
// of them in a populated sector.
let _mountScanFrame = -99, _mountScanResult = null;
function mountableHorse() {
  if (!player || player.mounted || player.hp <= 0 || isDead || isWin || killcamMode) return null;
  if (frameCount - _mountScanFrame < 6 && _mountScanResult !== null) {
    const c = _mountScanResult;
    // Re-validate the cached pick before handing it back -- it may have been
    // shot, or bolted, since the scan.
    if (c.hp > 0 && !c.dead && c.boltTimer <= 0 && dist(player.x, player.y, c.x, c.y) < 118) return c;
  }
  _mountScanFrame = frameCount;
  let best = null, bd = 118;
  for (const e of enemiesList) {
    if (e.eType !== "HORSE" || e.hp <= 0 || e.dead) continue;
    if (e.boltTimer > 0) continue;                    // catch it when it settles
    const d = dist(player.x, player.y, e.x, e.y);
    if (d < bd) { bd = d; best = e; }
  }
  _mountScanResult = best;
  return best;
}
// One button for both halves of the transaction.
function handleMountTap(mx, my) {
  if (!player || !isClickingBtn(mx, my)) return false;
  if (player.mounted) { player.dismount(); sfx.charge(); return true; }
  const h = mountableHorse();
  if (h) { player.mountHorse(h); sfx.charge(); return true; }
  return false;
}

function drawPromptBtn(txt) {
    fill(255, 200, 0); stroke(200, 100, 0); strokeWeight(2);
    rect(width/2 - 70, height - 120, 140, 50, 8);
    fill(0); noStroke(); textAlign(CENTER, CENTER); textSize(18); textFont('sans-serif');
    text(txt, width/2, height - 95);
}

function isClickingBtn(mx, my) {
    return (mx > width/2 - 70 && mx < width/2 + 70 && my > height - 120 && my < height - 70);
}

			// ==========================================
// PREVENT MOBILE PULL-TO-REFRESH & SCROLLING
// ==========================================
document.addEventListener('touchmove', function(e) { 
    e.preventDefault(); 
}, { passive: false });

function touchMoved() {
    return false;
}
// Live escort on the map, by sex. Used at save time to fold the soldiers who
// have already arrived back into the pending assignment, so a reload brings the
// same number in again rather than losing them with the entity list.
function countEscort(female) {
  let n = 0;
  if (typeof enemiesList === 'undefined') return 0;
  for (const e of enemiesList) {
    if (!e || !e.isFriendly || !e.isMilitary || e.hp <= 0 || e.dead) continue;
    const isF = String(e.eType || "").toUpperCase().indexOf("FEMALE") !== -1;
    if (isF === !!female) n++;
  }
  return n;
}

function saveGame() {
    let state = {
        currentLevel, isStoryMode, score, totalKills,
        smgUnlocked, dualSmgUnlocked, shotgunUnlocked, arUnlocked, rocketLauncherUnlocked, taserUnlocked,
        jetpackUnlocked, meleeUnlocked, jetpackFireExplosion, jetpackDoubleDash, meleeComboUnlocked, meleeFinisherUnlocked: window.meleeFinisherUnlocked,
        ninjaSuitUnlocked, explosiveArmorUnlocked, chemistSuitUnlocked, ninjaOwned: window.ninjaOwned, armorOwned: window.armorOwned, chemistOwned: window.chemistOwned,
        grenadesUnlocked, pGrenadeAmmo, pFlaskAmmo,
        popTotal, popUnassigned, popFarming, popMilitary, popScience, popArchitecture,
        journalRead, tabletPickedUp, swordPickedUp,
        towersDefeated: window.towersDefeated,
        nm0AmbushCleared: window.nm0AmbushCleared,

        // --- STORY ARC PROGRESSION ---
        // These decide whether a sector still builds its authored arena or has
        // converted to a streamed biome, so they have to survive a reload.
        nm0AmbushClearedStatus: window.nm0AmbushClearedStatus,
        northGateBreached: window.northGateBreached,
        northGateBreachedStatus: window.northGateBreachedStatus,
        southGateBreachedStatus: window.southGateBreachedStatus,
        southRoadAnnounced: window.southRoadAnnounced,
        undercityNorthBreached: window.undercityNorthBreached,
        undercitySouthBreached: window.undercitySouthBreached,
        ambushKind: window.ambushKind,
        nm0HqCleared: window.nm0HqCleared,
        armorBlueprintPickedUp: window.armorBlueprintPickedUp,
        farmerBlueprintUnlocked: window.farmerBlueprintUnlocked,
        genocideRouteActive: window.genocideRouteActive,
        genocideAmbushCleared: window.genocideAmbushCleared,
        postAmbushCutscenePlayed: window.postAmbushCutscenePlayed,

                farmXP: window.farmXP || 0, milXP: window.milXP || 0, sciXP: window.sciXP || 0, archXP: window.archXP || 0,
        farmLvl: window.farmLvl || 1, milLvl: window.milLvl || 1, sciLvl: window.sciLvl || 1, archLvl: window.archLvl || 1,

        inTownCutscene, townPhase, townTimer, 
        objectiveTimer,
        inPostAmbushCutscene, postAmbushPhase, 
        inWorldBuildingMenu, inOverworldView,
        statVit, statMen, statPhy, statObe, statInt, 
        darchonCallCompleted,
        militaryToBring: window.militaryToBring,
        playerHp: player ? player.hp : 100,
        playerShield: player ? player.shield : 100,
        playerX: player ? player.x : null,
        playerY: player ? player.y : null,

        // --- RESOURCES ---
        resources: window.resources || { WOOD: 0, METAL: 0, STONE: 0 },
        pickaxeOwned: !!window.pickaxeOwned,
        meleeToolSel: window.meleeToolSel || "NONE",
        swordEquipped: window.swordEquipped !== false,

        // --- CONSTRUCTION ---
        // Every sector's sites, not just this one's: a warehouse half up in
        // Stick City has to still be half up after a reload in the Undercity.
        // Flattened rather than stored by reference, because buildSiteSolids()
        // hands each solid a `site` back-pointer and JSON will not take a
        // cycle. Barriers ride along in the same list they now live in.
        buildSites: (typeof buildSites !== 'undefined' ? buildSites : []).map((s) => ({
            level: s.level, kind: s.kind, x: s.x, y: s.y, w: s.w, h: s.h,
            progress: s.progress, done: !!s.done, marked: !!s.marked
        })),
        playerBarriers: (typeof playerStructures !== 'undefined' ? playerStructures : [])
            .filter((b) => b.isUBarrier)
            .map((b) => ({ x: b.x, y: b.y, w: b.w, h: b.h, hp: b.hp, maxHp: b.maxHp, level: b.buildLevel })),

        // --- CUTSCENES ---
        // Which beats have played, by name. Everything else here is the state
        // of a cutscene that is mid-run; storyBeats is the record of the ones
        // that finished, so a reload cannot replay one.
        storyBeats: window.storyBeats || {},
        prologuePhase, storyPhase, inStoryIntro, inStoryRoom,
        inUpstairsRoom, upstairsPhase, tvWatched, hasSword,
        inFarmCutscene, farmPhase, inFarmPostCutscene, farmPostPhase,
        inLvl4Cutscene, lvl4Phase, lvl4Timer,
        inDarchonCall, callPhase,

        // --- AMBUSHES ---
        // All three of them. An ambush is a live counter plus a spawn budget:
        // saving one without the other reloads into a fight that can never be
        // finished, because checkAmbushCleared() waits on ambushSpawnsRemaining.
        nm0AmbushActive, nm0AmbushKills,
        ambushSpawnsRemaining: window.ambushSpawnsRemaining || 0,
        farmAmbushActive,
        farmAmbushKills: window.farmAmbushKills || 0,
        farmAmbushCleared: window.farmAmbushCleared || false,
        nm0AmbushClearedFlag: window.nm0AmbushCleared || false,

        // --- THE ESCORT ---
        // Soldiers the player marched in with. Once they have landed they are
        // allies on the map rather than a pending assignment, and the map is not
        // saved -- so the live ones are folded back into the pending counts and
        // re-spawned on load, which is the same path a normal arrival takes.
        militaryToBringM: (window.militaryToBringM || 0) + countEscort(false),
        militaryToBringF: (window.militaryToBringF || 0) + countEscort(true),

        // --- NEW FOR TOWN PERSISTENCE ---
        townsData: typeof townsData !== 'undefined' ? townsData : null,
        // The ledger itself rides along inside townsData (popSeeded, popKilled,
        // popGranted are plain fields on it). These two are the escort's
        // paperwork and live on window, so they have to be named.
        escortHome: window.escortHome || null,
        escortWasF: window.escortWasF || 0,
        viewingTownId: typeof viewingTownId !== 'undefined' ? viewingTownId : 1,

        // --- BIOME WORLD PERSISTENCE ---
        // Chunk layout is fully procedural, so only the deltas need storing.
        worldTimeMs: typeof worldTimeMs !== 'undefined' ? worldTimeMs : 0,
        // The sky, and where it is in its own cycle. isRaining alone is not the
        // weather: lastWeatherRollHour is what says whether this hour's roll has
        // already happened, and without it a reload either re-rolls immediately
        // or suppresses the next roll for a full in-game hour.
        isRaining: typeof isRaining !== 'undefined' ? isRaining : false,
        lastWeatherRollHour: typeof lastWeatherRollHour !== 'undefined' ? lastWeatherRollHour : -1,
        currentBiome: typeof currentBiome !== 'undefined' ? currentBiome : 1,
        biomeState: typeof biomeState !== 'undefined' ? biomeState : {}
    };
    localStorage.setItem('urbanTwinStickSave', JSON.stringify(state));
    streakMsgText = "GAME SAVED!";
    streakMsgTimer = 90;
}

function loadGame() {
    let saved = localStorage.getItem('urbanTwinStickSave');
    if (saved) {
        let state = JSON.parse(saved);
        isStoryMode = state.isStoryMode;

        // --- RESTORE STORY ARC PROGRESSION FIRST ---
        // startAtLevel() builds the map, and whether a sector builds its
        // authored arena or a streamed biome is decided by these flags plus
        // townsData. They have to be in place before the map is generated,
        // otherwise every save reloads into the wrong world.
        if (state.townsData) townsData = state.townsData;
        consolidateLegacyIntoPool();
        window.escortHome = state.escortHome || null;
        window.escortWasF = state.escortWasF || 0;
        if (state.viewingTownId) viewingTownId = state.viewingTownId;
        if (state.biomeState) biomeState = state.biomeState;
        if (state.currentBiome) currentBiome = state.currentBiome;
        if (typeof state.worldTimeMs === 'number') worldTimeMs = state.worldTimeMs;
        window.nm0AmbushClearedStatus = state.nm0AmbushClearedStatus || false;
        window.northGateBreached = state.northGateBreached || false;
        window.northGateBreachedStatus = state.northGateBreachedStatus || false;
        window.southGateBreachedStatus = state.southGateBreachedStatus || false;
        window.southRoadAnnounced = state.southRoadAnnounced || false;
        window.undercityNorthBreached = state.undercityNorthBreached || false;
        window.undercitySouthBreached = state.undercitySouthBreached || false;
        window.ambushKind = state.ambushKind || null;
        window.nm0HqCleared = state.nm0HqCleared || false;
        window.armorBlueprintPickedUp = state.armorBlueprintPickedUp || false;
        window.farmerBlueprintUnlocked = state.farmerBlueprintUnlocked || false;
        window.genocideRouteActive = state.genocideRouteActive || false;
        window.genocideAmbushCleared = state.genocideAmbushCleared || false;
        window.postAmbushCutscenePlayed = state.postAmbushCutscenePlayed || false;
        window.towersDefeated = state.towersDefeated || false;
        window.storyBeats = state.storyBeats || {};

        // The escort has to be pending BEFORE the level is built, because
        // legacyStartAtLevel() is what spawns it -- exactly as it does on a
        // normal arrival. Restored after startAtLevel (which is where it used
        // to be) the soldiers never landed, and the counts then sat there
        // waiting to conjure a second escort at the next level entry.
        window.militaryToBringM = state.militaryToBringM || 0;
        window.militaryToBringF = state.militaryToBringF || 0;

        startAtLevel(state.currentLevel, true); // true = skip hard reset

        // --- CRITICAL FIX: Restore flags AFTER startAtLevel so they don't get overwritten! ---
        window.towersDefeated = state.towersDefeated; 
        window.nm0AmbushCleared = state.nm0AmbushCleared;
        nm0AmbushActive = state.nm0AmbushActive || false; 
        nm0AmbushKills = state.nm0AmbushKills || 0; 
        inTownCutscene = state.inTownCutscene || false;
        window.ambushSpawnsRemaining = state.ambushSpawnsRemaining || 0;
        // Restored again here: it is set before startAtLevel() for the map
        // builder's benefit, and legacyStartAtLevel() nulls it on every entry.
        window.ambushKind = state.ambushKind || null;

        // --- CUTSCENES ---
        // Restored after startAtLevel(), which resets every one of them for a
        // fresh entry. A save made mid-cutscene comes back mid-cutscene.
        window.storyBeats = state.storyBeats || {};
        prologuePhase = state.prologuePhase || 0;
        storyPhase = state.storyPhase || 0;
        inStoryIntro = state.inStoryIntro || false;
        inStoryRoom = state.inStoryRoom || false;
        inUpstairsRoom = state.inUpstairsRoom || false;
        upstairsPhase = state.upstairsPhase || 0;
        tvWatched = state.tvWatched || false;
        hasSword = state.hasSword || false;
        inFarmCutscene = state.inFarmCutscene || false;
        farmPhase = state.farmPhase || 0;
        inFarmPostCutscene = state.inFarmPostCutscene || false;
        farmPostPhase = state.farmPostPhase || 0;
        inLvl4Cutscene = state.inLvl4Cutscene || false;
        lvl4Phase = state.lvl4Phase || 0;
        lvl4Timer = state.lvl4Timer || 0;
        inDarchonCall = state.inDarchonCall || false;
        callPhase = state.callPhase || 0;
        inPostAmbushCutscene = state.inPostAmbushCutscene || false;
        postAmbushPhase = state.postAmbushPhase || 0;
        townPhase = state.townPhase || 0;
        townTimer = state.townTimer || 0;
        objectiveTimer = state.objectiveTimer || 0;

        // --- RESOURCES ---
        window.resources = state.resources || { WOOD: 0, METAL: 0, STONE: 0 };
        for (const k of RESOURCE_KINDS) if (typeof window.resources[k] !== 'number') window.resources[k] = 0;
        window.pickaxeOwned = state.pickaxeOwned !== undefined ? !!state.pickaxeOwned : true;
        // setMeleeTool keeps swordEquipped in step, which is what the swing code
        // and the hand art actually read.
        setMeleeTool(state.meleeToolSel || (state.swordEquipped ? "SWORD" : "NONE"));

        // --- CONSTRUCTION ---
        // After startAtLevel(), which regenerates the world and would otherwise
        // wipe the structures straight back out of buildings[]. The `site`
        // back-pointers are rebuilt by republishPlayerStructures(), not saved.
        buildSites = Array.isArray(state.buildSites) ? state.buildSites.map((s) => ({
            level: Number(s.level) || 1, kind: s.kind,
            x: Number(s.x) || 0, y: Number(s.y) || 0,
            w: Number(s.w) || (BLUEPRINTS[s.kind] ? BLUEPRINTS[s.kind].w : 160),
            h: Number(s.h) || (BLUEPRINTS[s.kind] ? BLUEPRINTS[s.kind].h : 140),
            progress: Math.min(1, Math.max(0, Number(s.progress) || 0)), done: !!s.done,
            marked: !!s.marked
        })).filter((s) => BLUEPRINTS[s.kind]) : [];
        playerStructures = (Array.isArray(state.playerBarriers) ? state.playerBarriers : [])
            .map((b) => ({ x: b.x, y: b.y, w: b.w || 200, h: b.h || 200, isUBarrier: true,
                           hp: b.hp || 1000, maxHp: b.maxHp || 1000, hitFlash: 0,
                           isPlayerBuilt: true, buildLevel: b.level }));
        buildGhost = null;
        republishPlayerStructures();

        // --- AMBUSHES ---
        farmAmbushActive = state.farmAmbushActive || false;
        window.farmAmbushKills = state.farmAmbushKills || 0;
        window.farmAmbushCleared = state.farmAmbushCleared || false;
        if (state.nm0AmbushClearedFlag !== undefined) window.nm0AmbushCleared = state.nm0AmbushClearedFlag;

        score = state.score || 0;
        totalKills = state.totalKills || 0;
        
        smgUnlocked = state.smgUnlocked; dualSmgUnlocked = state.dualSmgUnlocked; shotgunUnlocked = state.shotgunUnlocked; 
        arUnlocked = state.arUnlocked; rocketLauncherUnlocked = state.rocketLauncherUnlocked; taserUnlocked = state.taserUnlocked;
        jetpackUnlocked = state.jetpackUnlocked; meleeUnlocked = state.meleeUnlocked; jetpackFireExplosion = state.jetpackFireExplosion; 
        jetpackDoubleDash = state.jetpackDoubleDash; meleeComboUnlocked = state.meleeComboUnlocked; window.meleeFinisherUnlocked = state.meleeFinisherUnlocked;
        ninjaSuitUnlocked = state.ninjaSuitUnlocked; explosiveArmorUnlocked = state.explosiveArmorUnlocked; chemistSuitUnlocked = state.chemistSuitUnlocked; 
        window.ninjaOwned = state.ninjaOwned; window.armorOwned = state.armorOwned; window.chemistOwned = state.chemistOwned;
        
        grenadesUnlocked = state.grenadesUnlocked; pGrenadeAmmo = state.pGrenadeAmmo; pFlaskAmmo = state.pFlaskAmmo;
        
        // popTotal / popUnassigned / popFarming / popMilitary / popScience /
        // popArchitecture are DERIVED from the ledger and are recomputed by
        // loadLedgerIntoWindow(). Restoring them from the save put a stale copy
        // of some other sector's numbers in front of the record.
        loadLedgerIntoWindow(state.viewingTownId || currentLevel);
        statVit = state.statVit || 1; statMen = state.statMen || 1; statPhy = state.statPhy || 1; statObe = state.statObe || 1; statInt = state.statInt || 1;
        
        if (state.biomeState) biomeState = state.biomeState;
        if (state.currentBiome) currentBiome = state.currentBiome;
        if (typeof state.worldTimeMs === 'number') worldTimeMs = state.worldTimeMs;
        // Put the sky back where it was, rather than rolling a new one.
        //
        // Loading used to force isRaining false and set lastWeatherRollHour to
        // the current hour, which threw away the storm you saved in AND
        // suppressed the next roll for the rest of that hour. Restoring the
        // SAVED roll hour is what makes both halves right: if the save was taken
        // after this hour's roll the next one is due at the hour boundary, and
        // if it was taken before, it fires almost immediately. The rain
        // probability drives it either way.
        //
        // applyBiomeWeather() rather than initBiomeWeather(), because init
        // re-rolls isRaining from scratch, which is the thing we are restoring.
        isRaining = !!state.isRaining;
        lastWeatherRollHour = (typeof state.lastWeatherRollHour === 'number')
                              ? state.lastWeatherRollHour : Math.floor(worldHour());
        weather = null;
        applyBiomeWeather();
        if (state.townsData) townsData = state.townsData;
        consolidateLegacyIntoPool();
        window.escortHome = state.escortHome || null;
        window.escortWasF = state.escortWasF || 0;
        if (state.viewingTownId) viewingTownId = state.viewingTownId;
        window.farmXP = Number(state.farmXP) || 0; window.milXP = Number(state.milXP) || 0; 
        window.sciXP = Number(state.sciXP) || 0; window.archXP = Number(state.archXP) || 0;
        window.farmLvl = Number(state.farmLvl) || 1; window.milLvl = Number(state.milLvl) || 1; 
        window.sciLvl = Number(state.sciLvl) || 1; window.archLvl = Number(state.archLvl) || 1;
        window.archBarrierReady = false;

        journalRead = state.journalRead; tabletPickedUp = state.tabletPickedUp; swordPickedUp = state.swordPickedUp;
        darchonCallCompleted = state.darchonCallCompleted;
window.militaryToBring = state.militaryToBring || 0;
        // townPhase / townTimer / objectiveTimer / the post-ambush pair are
        // restored with the rest of the cutscene block above.
        inWorldBuildingMenu = state.inWorldBuildingMenu || false; inOverworldView = state.inOverworldView || false;

        // --- CUTSCENE ACTORS ---
        // Speakers are object references into enemiesList, and the entity list
        // is not saved. A cutscene restored mid-run therefore comes back with
        // null speakers and reads .x off them on the next frame. Re-cast from
        // whoever is actually standing here, and if the sector has nobody left
        // to say the lines, close the scene rather than crash in it.
        if (inTownCutscene || inPostAmbushCutscene) {
            const cast = enemiesList.filter(e => e && e.isFriendly && e.hp > 0 && !e.dead && !e.isMilitary);
            cast.sort((a, b) => {
                const ia = insideSector(a.x, a.y, 200) ? 0 : 1;
                const ib = insideSector(b.x, b.y, 200) ? 0 : 1;
                if (ia !== ib) return ia - ib;
                return dist(player.x, player.y, a.x, a.y) - dist(player.x, player.y, b.x, b.y);
            });
            if (cast.length) {
                townSpeaker1 = cast[0];
                townSpeaker2 = cast.length > 1 ? cast[1] : cast[0];
                if (inPostAmbushCutscene) window.allies = cast;
            } else {
                inTownCutscene = false; inPostAmbushCutscene = false;
                townPhase = 0; postAmbushPhase = 0;
            }
        }
        if (inFarmCutscene || inFarmPostCutscene) {
            farmSpeaker = enemiesList.find(e => e && e.hp > 0 && !e.dead &&
                (e.eType === "FARMER_MALE" || e.eType === "FARMER_FEMALE")) || null;
            if (!farmSpeaker) { inFarmCutscene = false; inFarmPostCutscene = false; farmPhase = 0; farmPostPhase = 0; }
        }
        if (inLvl4Cutscene) {
            tanLeader = enemiesList.find(e => e && e.hp > 0 && !e.dead && e.eType === "MILITARY_NEUTRAL") || null;
            if (!tanLeader) { inLvl4Cutscene = false; lvl4Phase = 0; }
        }

        if (player) {
            player.hp = state.playerHp || 100;
            player.shield = state.playerShield || 100;
            if (state.playerX !== null && state.playerY !== null) {
                player.x = state.playerX;
                player.y = state.playerY;
            }
        }
    let mult = (window.milLvl >= 2) ? 2 : 1;
    if (window.archLvl >= 2) window.archBarrierReady = true;

        if (smgUnlocked) { player.mags["MACHINE GUN"] = 3; player.weaponAmmo["MACHINE GUN"] = WEAPONS.SMG.maxAmmo; }
        if (dualSmgUnlocked) { player.mags["DUAL SMGS"] = 3; player.weaponAmmo["DUAL SMGS"] = WEAPONS.DUAL_SMG.maxAmmo; }
        if (arUnlocked) { player.mags["ASSAULT RIFLE"] = 3; player.weaponAmmo["ASSAULT RIFLE"] = WEAPONS.ASSAULT_RIFLE.maxAmmo; }
        if (shotgunUnlocked) { player.mags["SHOTGUN"] = 3; player.weaponAmmo["SHOTGUN"] = WEAPONS.SHOTGUN.maxAmmo; }
        if (rocketLauncherUnlocked) { player.mags["ROCKET LAUNCHER"] = 6; player.weaponAmmo["ROCKET LAUNCHER"] = WEAPONS.ROCKET_LAUNCHER.maxAmmo; }

        if (rocketLauncherUnlocked) player.currentWeapon = WEAPONS.ROCKET_LAUNCHER;
        else if (shotgunUnlocked) player.currentWeapon = WEAPONS.SHOTGUN;
        else if (arUnlocked) player.currentWeapon = WEAPONS.ASSAULT_RIFLE;
        else if (dualSmgUnlocked) player.currentWeapon = WEAPONS.DUAL_SMG;
        else if (smgUnlocked) player.currentWeapon = WEAPONS.SMG;
        else player.currentWeapon = WEAPONS.PISTOL;
        
                       // 1. If towers are defeated, physically delete them from the spawned map
        if (window.towersDefeated) {
            for (let i = buildings.length - 1; i >= 0; i--) {
                if (buildings[i].isTower) buildings.splice(i, 1);
            }
            
            // WIPE RANDOM HOSTILES BUT PRESERVE DEPLOYED MILITARY
            enemiesList = enemiesList.filter(e => e.isFriendly && e.isMilitary);
            
            // CALCULATE ACTUAL SURVIVING POPULATION
            let isTownEst = townsData && townsData[currentLevel] && townsData[currentLevel].established;
            let survivorCount = 0;
            
            // ONLY SPAWN SURVIVORS IF THE TOWN ISN'T ESTABLISHED YET
            if (!isTownEst) {
                survivorCount = Math.min(80, window.nm0AmbushCleared ? popTotal : Math.max(0, MAX_KILLS - totalKills));
            }
            
            // RE-SPAWN THE EXACT NUMBER OF ALLIES
            if (survivorCount > 0) {
                let allyType = (currentLevel === 2 && isStoryMode) ? "FEMALE_PISTOL" : "NORMAL";
                for (let i = 0; i < survivorCount; i++) {
                    let ax = player.x + random(-400, 400);
                    let ay = player.y + random(-400, 400);
                    let a = new Character(ax, ay, false, allyType);
                    
                    a.isFriendly = true;
                    a.hp = 300;
                    a.state = nm0AmbushActive ? "CHASE" : "IDLE";
                    
                    if (i === 0) townSpeaker1 = a;
                    if (i === 1) townSpeaker2 = a;
                    
                    enemiesList.push(a);
                }
                
                if (survivorCount === 1) townSpeaker2 = townSpeaker1;
                killcamTarget = {x: townSpeaker1.x, y: townSpeaker1.y};
            }

            // RE-SPAWN AMBUSH HOSTILES IF ACTIVE
                        // RE-SPAWN AMBUSH HOSTILES IF ACTIVE
            if (nm0AmbushActive) {
                let spawnY = (currentLevel === 1) ? 4950 : 1800;
                let aerY = (currentLevel === 1) ? 4900 : 1750;
                if (!window.ambushKind) window.ambushKind = "TOWER";

                // Keep the live counter and active spawns perfectly locked
                let activeToSpawn = Math.min(100, nm0AmbushKills);
                window.ambushSpawnsRemaining = Math.max(0, nm0AmbushKills - activeToSpawn);
                
                let remainingStandard = Math.ceil(activeToSpawn * 0.84);
                let remainingArmored = Math.ceil(activeToSpawn * 0.08);
                let remainingAerial = Math.ceil(activeToSpawn * 0.08);
                
                for(let i=0; i<remainingStandard; i++) {
                    let sX = random() > 0.5 ? 600 : -200;
                    let c = new Character(sX + random(-250, 250), spawnY + random(-50, 50), false, "ARMORED_STANDARD");
                    c.isAmbush = true;
                    enemiesList.push(c);
                }
                for(let i=0; i<remainingArmored; i++) {
                    let sX = random() > 0.5 ? 600 : -200;
                    let c = new Character(sX + random(-100, 100), spawnY + random(-50, 50), false, "ARMORED");
                    c.isAmbush = true;
                    enemiesList.push(c);
                }
                for(let i=0; i<remainingAerial; i++) {
                    let sX = random() > 0.5 ? 600 : -200;
                    let c = new Character(sX + random(-300, 300), aerY, false, "AERIAL");
                    c.isAmbush = true;
                    enemiesList.push(c);
                }
                
                for (let e of enemiesList) { 
                    if (!e.isFriendly) { e.state = "CHASE"; e.loseSightTimer = 3500; } 
                }
            }

            // TRIGGER CUTSCENE IF SAVED RIGHT AS TOWERS FELL
            //
            // Only if it has not already played. Every flag this keys off is
            // cleared by the beat that FOLLOWS the town scene -- nm0AmbushCleared
            // is reset by its own handler and the muster ends -- so after the
            // sector was liberated a reload put the player straight back into
            // the cutscene they had already watched. storyBeats is the record
            // that survives that.
            if (!window.nm0AmbushCleared && !nm0AmbushActive && !inTownCutscene &&
                !window.nm0AmbushClearedStatus &&
                !storyBeatDone("L" + currentLevel + "_TOWN")) {
                inTownCutscene = true; townPhase = 1; townTimer = 120;
            }
            
            // --- OVERWORLD LOAD STATE CATCH ---
            if (window.towersDefeated && !nm0AmbushActive && !inTownCutscene && !inPostAmbushCutscene && currentLevel > 0) {
                viewingTownId = currentLevel;
                
                if (townsData && townsData[currentLevel] && townsData[currentLevel].established) {
                    inOverworldView = true;
                    inWorldBuildingMenu = false;
                } else if (popTotal > 0) {
                    inWorldBuildingMenu = true;
                    inOverworldView = false;
                }

                // Repopulate the visual civilian sprites
                townCitizens = [];
                for (let i = 0; i < popFarming; i++) townCitizens.push(new Citizen(player.x + random(-400, 400), player.y + random(-400, 400), "FARMING"));
                for (let i = 0; i < popMilitary; i++) townCitizens.push(new Citizen(player.x + random(-400, 400), player.y + random(-400, 400), "MILITARY"));
                for (let i = 0; i < popScience; i++) townCitizens.push(new Citizen(player.x + random(-400, 400), player.y + random(-400, 400), "SCIENCE"));
                for (let i = 0; i < popArchitecture; i++) townCitizens.push(new Citizen(player.x + random(-400, 400), player.y + random(-400, 400), "ARCHITECTURE"));
            }
        }
    }
}

    

function issueSquadCommand(cmd, dir = "NORTH") {
    let allies = enemiesList.filter(e => e.isFriendly && !e.dead);
    
    for (let i = 0; i < allies.length; i++) {
        let ally = allies[i];
        
        // PRE-CALCULATE SLOT: Centers the squad (-2, -1, 0, 1, 2, etc.)
        ally.squadSlot = i - Math.floor(allies.length / 2);
        
        if (cmd === "FOLLOW") {
            ally.baseState = "FOLLOW"; 
        } 
        else if (cmd === "HOLD") {
            ally.baseState = "HOLD_PERIMETER"; 
            ally.holdPos = {x: ally.x, y: ally.y};
        } 
        else if (cmd === "SPREAD") {
            ally.baseState = "SEARCH_DIRECTION";
            ally.searchDir = ["NORTH", "SOUTH", "EAST", "WEST"][i % 4];
        }
        else if (cmd === "SEARCH") {
            ally.baseState = "SEARCH_DIRECTION";
            ally.searchDir = dir; 
        }
    }
    isPaused = false; 
    sfx.charge();
}
function drawMenuBtn(txt, x, y, w, h) {
    fill(255, 200, 0); stroke(200, 100, 0); strokeWeight(2);
    rect(x - w/2, y - h/2, w, h, 8);
    fill(0); noStroke(); textAlign(CENTER, CENTER); textSize(16); textFont('sans-serif');
    text(txt, x, y);
}

function triggerBugAmbush() {
    farmAmbushActive = true;
    window.farmAmbushKills = 500; // Set the total swarm size
    objectiveTimer = 360;
    streakMsgText = "PEST INFESTATION!";
    streakMsgTimer = 120;

    // Mobilize the farmers into a militia!
    for (let e of enemiesList) {
        if (e.eType === "FARMER_MALE" || e.eType === "FARMER_FEMALE") {
            e.isNeutral = false; 
            e.isFriendly = true; 
            e.hp = 300; // Buff their health so they can survive the swarm
            e.baseState = "HOLD_PERIMETER"; // Tell them to hold their ground
            e.holdPos = { x: e.x, y: e.y };
            
            // Upgrade their weapons
            e.currentWeapon = random() > 0.5 ? WEAPONS.SHOTGUN : WEAPONS.ASSAULT_RIFLE;
            e.weaponAmmo[e.currentWeapon.name] = e.currentWeapon.maxAmmo;
        }
    }

    // Spawn the first 50 bugs instantly
    for(let i = 0; i < 50; i++) {
        spawnFarmBug();
    }
}

function spawnFarmBug() {
    if (!farmAmbushActive || isDead || isWin) return;
    
    // 50/50 split between West and North-West spawns
    let isWest = random() > 0.5;
    let sX = isWest ? -1200 + random(-100, 100) : -1000 + random(-100, 100);
    let sY = isWest ? random(-150, 150) : -800 + random(-100, 100);

    let b = new Character(sX, sY, false, "BUG");
    b.state = "CHASE"; 
    b.loseSightTimer = 3000;
    enemiesList.push(b);
}
// --- NEW METER & UPGRADE SYSTEM ---


function checkLevelUps() {
    let req2 = 50; 
    if (window.farmLvl === 1 && window.farmXP >= req2) { 
        window.farmLvl = 2; streakMsgText = "FARMING LEVEL 2!"; streakMsgTimer = 120; sfx.charge(); 
        if (player) { player.maxHp = 125; player.hp += 25; }
        for (let e of enemiesList) if (e.isFriendly) { e.maxHp = (e.maxHp || 300) + 25; e.hp += 25; }
    }
    if (window.milLvl === 1 && window.milXP >= req2) { 
        window.milLvl = 2; streakMsgText = "MILITARY LEVEL 2!"; streakMsgTimer = 120; sfx.charge(); 
        if (player) player.triggerReload(); 
    }
    if (window.sciLvl === 1 && window.sciXP >= req2) { 
        window.sciLvl = 2; streakMsgText = "SCIENCE LEVEL 2!"; streakMsgTimer = 120; 
        chemistSuitUnlocked = true; window.chemistOwned = true; sfx.charge(); 
    }
    if (window.archLvl === 1 && window.archXP >= req2) { 
        window.archLvl = 2; streakMsgText = "ARCHITECTURE LEVEL 2!"; streakMsgTimer = 120; 
        window.archBarrierReady = true; sfx.charge(); 
    }
}

function buildBarrier() {
    if (!window.archBarrierReady) return;
    window.archBarrierReady = false;
    // Through playerStructures rather than straight into buildings[]: see the
    // construction block below for why anything the player puts in the world
    // has to survive rebuildWorldArrays().
    playerStructures.push({ x: player.x, y: player.y - 20, w: 200, h: 200, isUBarrier: true,
                            hp: 1000, maxHp: 1000, hitFlash: 0,
                            isPlayerBuilt: true, buildLevel: currentLevel });
    republishPlayerStructures();
    sfx.charge();
}

// ############################################################################
// ##  CONSTRUCTION                                                          ##
// ############################################################################
//
// The architecture department made visible. The player picks a blueprint from
// the pause menu, walks a ghost footprint to a clear patch of ground, and the
// crew raises it over the following in-game days.
//
// Three things this has to get right, and the third is the one that bites:
//
// 1. **Rate is a function of the assigned department, not of the sprites.**
//    `townCitizens` is the visualisation and is rebuilt from the same counts
//    whenever the Directive is confirmed; tying progress to the sprites would
//    stall every site each time the roster was repopulated.
// 2. **Progress accrues against `worldClockDtMs`** -- the same millisecond
//    delta the sun and the production meters run on -- so a day of building is
//    a day of building at any frame rate, and it keeps accruing while the
//    player is in a different level. That is what "it remains being built"
//    means: `updateBuildSites()` walks every site in every sector, and only
//    the ones in `currentLevel` are ever drawn.
// 3. **`buildings[]` is REPLACED wholesale** by `ChunkManager.rebuildWorldArrays()`
//    every time chunk residency changes -- in a streamed biome, every time you
//    cross a chunk edge, which is constantly. Anything the player puts in the
//    world therefore has to live in its own list that the rebuild republishes,
//    exactly the way the travel anchors do. `buildBarrier()` has always pushed
//    straight into `buildings[]` and has always been quietly swept away a few
//    strides later; it goes through the same list now.

// Footprints are the ghost, the ground the crew clears and the collision box,
// all one number -- so what the player lines up is what they get.
//
// Authored at 1x and multiplied by BUILD_SCALE, which is the only number to
// touch if the whole set wants re-proportioning: every piece of structure art
// below is written in fractions of its own footprint rather than in absolute
// units, so it reads the same at any scale. At the 20 units to the metre a
// parked car sets, 2.25x puts the warehouse at 26 x 17 m -- a real shed you
// walk the length of, rather than the garden hut 1x was or the airfield 9x was.
const BUILD_SCALE = 2.25;
const BLUEPRINTS = {
    WAREHOUSE:  { label: "WAREHOUSE",      w: Math.round(230 * BUILD_SCALE), h: Math.round(150 * BUILD_SCALE),
                  blurb: "Bulk storage. Corrugated shell, loading bays." },
    LABORATORY: { label: "LABORATORY",     w: Math.round(170 * BUILD_SCALE), h: Math.round(140 * BUILD_SCALE),
                  blurb: "Clean rooms and roof plant for the science wing." },
    RANGE:      { label: "SHOOTING RANGE", w: Math.round(260 * BUILD_SCALE), h: Math.round(110 * BUILD_SCALE),
                  blurb: "Firing line, six lanes, earth backstop." },
    FARM:       { label: "BARN & FIELD",   w: Math.round(260 * BUILD_SCALE), h: Math.round(190 * BUILD_SCALE),
                  blurb: "Gambrel barn with a worked field alongside." }
};
const BUILD_ORDER = ["WAREHOUSE", "LABORATORY", "RANGE", "FARM"];

// 1% of a structure per in-game day per assigned architect, so a full hundred
// raises one in a single day. Architecture level multiplies it -- the same
// department stat the Directive already advertises as "Build Speed".
const BUILD_DAY_PER_UNIT = 0.01;

let buildSites = [];          // every site in every sector; the save's record
let playerStructures = [];    // the current sector's solids, republished on rebuild
let buildGhost = null;        // { kind, x, y, w, h, ok } only while placing
let buildMenuPage = 0;

function buildCrew() {
    return (Number(window.popArchitectureM) || 0) + (Number(window.popArchitectureF) || 0);
}
function buildSpeedMult() { return Math.max(1, Number(window.archLvl) || 1); }
// Days to finish from a standing start, for the blueprint list. Infinity reads
// as "nobody assigned", which is the honest answer.
function buildEtaDays(fraction) {
    const rate = buildCrew() * BUILD_DAY_PER_UNIT * buildSpeedMult();
    return rate > 0 ? (fraction / rate) : Infinity;
}

// Ground has to be clear of solids, of authored geometry, of standing water and
// of other sites. Same question the chunk generator asks before it places
// anything, asked through the same helpers.
// A build site is a CLEARED lot, and clearing it is the first day's work.
// Ground scatter -- a tree, a boulder, a log pile -- is not an obstruction; the
// crew takes it out and the timber and stone go to stores. Anything that is not
// scatter still refuses the site: a standing structure, a river, hand-authored
// ground, another site.
//
// Without this the 9x footprints were unplaceable. Measured over the woodland:
// a 2070 x 1350 warehouse found 0 clear spots in 81 sampled; treating scatter
// as clearable puts it back to roughly what the small footprints saw.
// Anything up to about seven metres across, plus anything the pickaxe already
// recognises as a resource. Deliberately a size rule rather than a list of
// flags: the scatter that fills a biome is a different set in every one of them
// -- timber and boulders in the woods, cactus and hay and crates in Dry Gulch --
// and enumerating them all is a list that goes stale the next time a biome gets
// dressed. What is NOT clearable is the short list that matters: a river, a
// bridge deck, hand-authored ground, another structure, and any building big
// enough that flattening it would be a decision rather than a morning's work.
// Judged on AREA, not on the longer side: a fence panel is 300 x 12 and a hedge
// run is longer still, and both are a morning with a chain rather than a
// decision. 9000 sq units is about a ten-metre square -- a cactus, a hay bale,
// a crate, a signpost, a fence bay, a tree. A cabin at 200 x 160 is four times
// that and stays put, which is the line worth drawing.
const BUILD_CLEAR_AREA = 9000;
const BUILD_CLEAR_MAX = 520;   // a fence bay in Dry Gulch runs to ~470
function buildClearable(o) {
    if (!o || o.isAuthored || o.isRiver || o.isDeck || o.isPlayerBuilt) return false;
    if (o.isGovFortress || o.isGiantBarrier || o.isPond || o.isWater) return false;
    if (o.isBiomeProp && (o.propType === "BRIDGE" || o.propType === "CANALBRIDGE" ||
                          o.propType === "BOARDWALK" || o.propType === "HELIPAD" ||
                          o.propType === "CHECKPOINT" || o.propType === "OUTPOST" ||
                          o.propType === "BORDERWALL")) return false;
    if (typeof harvestProfile === 'function' && harvestProfile(o)) return true;
    const w = o.w || 0, h = o.h || 0;
    return Math.max(w, h) <= BUILD_CLEAR_MAX && w * h <= BUILD_CLEAR_AREA;
}

function buildSpotClear(x, y, w, h) {
    for (const o of activeBuildings) {
        // Ground, not mass. A lawn or a worked field is something you build ON.
        if (o.isGrassLot && !o.isPond) continue;
        if (o.isCropField || o.isParkingLot) continue;
        if (buildClearable(o)) continue;
        if (Math.abs(x - o.x) < (w + (o.w || 0)) / 2 + 16 &&
            Math.abs(y - o.y) < (h + (o.h || 0)) / 2 + 16) return false;
    }
    if (typeof hitsAuthored === 'function' && hitsAuthored(x, y, w, h, 20)) return false;
    if (typeof waterDepthAt === 'function') {
        // Sampled on a grid rather than at five points: five was plenty for a
        // 230-unit shed and would step clean over a whole pond inside a
        // 2000-unit one.
        const cols = Math.max(2, Math.ceil(w / 200)), rows = Math.max(2, Math.ceil(h / 200));
        for (let i = 0; i <= cols; i++) for (let j = 0; j <= rows; j++) {
            const px = x - w / 2 + (w * i) / cols, py = y - h / 2 + (h * j) / rows;
            if (waterDepthAt(px, py) > 0.02) return false;
        }
    }
    for (const s of buildSites) {
        if (s.level !== currentLevel) continue;
        if (Math.abs(x - s.x) < (w + s.w) / 2 + 24 && Math.abs(y - s.y) < (h + s.h) / 2 + 24) return false;
    }
    return true;
}

function startBuildPlacement(kind) {
    const bp = BLUEPRINTS[kind];
    if (!bp) return false;
    buildGhost = { kind: kind, x: player.x, y: player.y, w: bp.w, h: bp.h, ok: false };
    isPaused = false;
    pauseMenuState = "MAIN";
    window.lastPauseTime = millis();
    if (sfx && sfx.charge) sfx.charge();
    return true;
}
function cancelBuildPlacement() {
    buildGhost = null;
    if (sfx && sfx.reload) sfx.reload();
}
// The ghost rides in front of the player on the aim angle, so the left stick
// carries it and the right stick swings it around -- no second cursor to learn.
function updateBuildPlacement() {
    if (!buildGhost || !player) return;
    // The reach is capped, so a small footprint sits in front of the player the
    // way it always did and a large one closes over them -- you stand in the
    // middle of the ground you are laying out, which is the only thing that
    // works once a footprint is wider than the screen.
    const reach = Math.min(110 + Math.max(buildGhost.w, buildGhost.h) * 0.5, 300);
    buildGhost.x = player.x + Math.cos(player.aimAngle) * reach;
    buildGhost.y = player.y + Math.sin(player.aimAngle) * reach;
    buildGhost.ok = buildSpotClear(buildGhost.x, buildGhost.y, buildGhost.w, buildGhost.h);
}
// How far out the camera has to pull for the whole footprint to be on screen.
// Returns null when nothing is being placed, so the caller keeps its own zoom.
function buildPlacementZoom() {
    if (!buildGhost) return null;
    const reach = Math.min(110 + Math.max(buildGhost.w, buildGhost.h) * 0.5, 300);
    // Camera sits on the player, so the span to cover is the player out to the
    // ghost's far edge, in both axes, with a margin.
    const spanX = (reach + buildGhost.w / 2) * 2.35;
    const spanY = (reach + buildGhost.h / 2) * 2.35;
    return Math.max(0.10, Math.min(0.66, Math.min(width / spanX, height / spanY)));
}
// Take the scatter off the lot and bank what it was worth. Credited straight
// rather than through spawnResourceDrop(), because a hundred-metre footprint
// can hold thirty trees and that is thirty scattered pickup piles to walk over.
function clearBuildLot(x, y, w, h) {
    const won = {};
    for (let i = buildings.length - 1; i >= 0; i--) {
        const o = buildings[i];
        if (!buildClearable(o)) continue;
        if (Math.abs(x - o.x) > (w + (o.w || 0)) / 2 || Math.abs(y - o.y) > (h + (o.h || 0)) / 2) continue;
        const hv = harvestProfile(o);
        if (hv) { won[hv.kind] = (won[hv.kind] || 0) + hv.yield; addResource(hv.kind, hv.yield); }
        // A felled tree loses its canopy, same as one taken down with a pick.
        if (o.isTreeTrunk && typeof chunkMgr !== 'undefined' && chunkMgr) {
            for (const ch of chunkMgr.chunks.values()) {
                for (let d = ch.decor.length - 1; d >= 0; d--) {
                    const dc = ch.decor[d];
                    if ((dc.t === "TREE" || dc.t === "PINE" || dc.t === "SNAG") &&
                        Math.abs(dc.x - o.x) < 6 && Math.abs(dc.y - o.y) < 6) ch.decor.splice(d, 1);
                }
            }
        }
        if (o.chunkKey && typeof markPropDestroyed === 'function' && BIOME_ACTIVE) {
            markPropDestroyed(currentBiome, o.chunkKey);
        }
        buildings.splice(i, 1);
        const ai = activeBuildings.indexOf(o);
        if (ai > -1) { activeBuildings.splice(ai, 1); invalidateColIndex(); }
    }
    return won;
}

function confirmBuildPlacement() {
    if (!buildGhost || !buildGhost.ok) return false;
    const won = clearBuildLot(buildGhost.x, buildGhost.y, buildGhost.w, buildGhost.h);
    const parts = [];
    for (const k of RESOURCE_KINDS) if (won[k]) parts.push("+" + won[k] + " " + k);
    if (parts.length) floatingScores.push({ y: 100, text: "LOT CLEARED  " + parts.join("  "), life: 110, maxLife: 110 });
    buildSites.push({
        level: currentLevel, kind: buildGhost.kind,
        x: Math.round(buildGhost.x), y: Math.round(buildGhost.y),
        w: buildGhost.w, h: buildGhost.h, progress: 0, done: false
    });
    buildGhost = null;
    republishPlayerStructures();
    streakMsgText = "GROUND BROKEN"; streakMsgTimer = 110;
    if (sfx && sfx.charge) sfx.charge();
    return true;
}

// Every site in every sector advances, which is the whole point -- walk away
// from a half-built warehouse, clear a biome, come back and it is up.
function updateBuildSites() {
    const dt = worldClockDtMs;
    if (!(dt > 0) || buildSites.length === 0) return;
    const crew = buildCrew();
    if (crew <= 0) return;
    const rate = (crew * BUILD_DAY_PER_UNIT * buildSpeedMult()) / DAY_MS;
    let finished = false;
    for (const s of buildSites) {
        if (s.done) continue;
        s.progress = Math.min(1, s.progress + rate * dt);
        if (s.progress >= 1) {
            s.done = true;
            finished = true;
            if (s.level === currentLevel) {
                streakMsgText = (BLUEPRINTS[s.kind] ? BLUEPRINTS[s.kind].label : "STRUCTURE") + " COMPLETE";
                streakMsgTimer = 140;
                if (sfx && sfx.charge) sfx.charge();
            }
        }
    }
    if (finished) republishPlayerStructures();
}

// The solids one site contributes. A site under construction is a hoarded lot
// you cannot walk through; a finished one is the structure, plus whatever
// ground the blueprint lays down beside it.
// Where the supply truck parks. Broadside to the south of the site and clear of
// the hoarding, so all three of its unloading faces -- both flanks of the
// container and its rear -- are approachable without anyone walking through the
// site. Derived from the site rather than stored, so it cannot drift.
const TRUCK_W = 250, TRUCK_H = 92;
function buildTruckAt(s) {
    return { x: s.x, y: s.y + s.h / 2 + 130, w: TRUCK_W, h: TRUCK_H };
}
// The three places a hauler can reach into the container: left flank, right
// flank, tailgate. The cab is the east end, so the container's middle sits back
// from the truck's own centre.
function truckSlot(t, i) {
    const cx = t.x - t.w * 0.16;
    if (i === 0) return { x: cx, y: t.y - t.h / 2 - 22 };
    if (i === 1) return { x: cx, y: t.y + t.h / 2 + 22 };
    return { x: t.x - t.w / 2 - 24, y: t.y };
}

function buildSiteSolids(s) {
    const out = [];
    if (!s.done) {
        out.push({ x: s.x, y: s.y, w: s.w, h: s.h, isBuildSite: true, site: s,
                   isPlayerBuilt: true, buildLevel: s.level });
        // The materials lorry, parked for as long as there is a job. It is a
        // solid so the player has to walk round it like any other vehicle;
        // citizens do not collide with buildings, so it never blocks the crew.
        const t = buildTruckAt(s);
        out.push({ x: t.x, y: t.y, w: t.w, h: t.h, isBuildTruck: true, site: s,
                   isPlayerBuilt: true, buildLevel: s.level });
        return out;
    }
    if (s.kind === "FARM") {
        // Barn on the west third, worked ground on the rest. The field is a
        // ground lot, so it draws under the player and never blocks a step.
        const bw = Math.round(s.w * 0.42);
        out.push({ x: s.x - (s.w - bw) / 2, y: s.y, w: bw, h: s.h * 0.8,
                   isBuiltStructure: true, kind: s.kind, site: s,
                   isPlayerBuilt: true, buildLevel: s.level });
        out.push({ x: s.x + bw / 2, y: s.y, w: s.w - bw, h: s.h, isCropField: true,
                   isPlayerBuilt: true, buildLevel: s.level });
        return out;
    }
    out.push({ x: s.x, y: s.y, w: s.w, h: s.h, isBuiltStructure: true, kind: s.kind, site: s,
               isPlayerBuilt: true, buildLevel: s.level });
    return out;
}

// Rebuild the current sector's structure list and get it into buildings[].
// Called on level entry, on placement and on completion -- and appended again
// by rebuildWorldArrays() every time the chunk streamer republishes the world.
function republishPlayerStructures() {
    const keep = playerStructures.filter((b) => b.isUBarrier && b.buildLevel === currentLevel);
    playerStructures = keep;
    for (const s of buildSites) {
        if (s.level !== currentLevel) continue;
        for (const b of buildSiteSolids(s)) playerStructures.push(b);
    }
    for (let i = buildings.length - 1; i >= 0; i--) if (buildings[i].isPlayerBuilt) buildings.splice(i, 1);
    for (const b of playerStructures) buildings.push(b);
    lastActiveUpdate = 0;
    activeBuildings = [];
    if (typeof updateActiveWorld === 'function') updateActiveWorld();
}

// A crew member's own patch of the perimeter, so twenty architects ring the
// site instead of standing in one heap on its centre.
function buildSlotFor(s, seed) {
    const p = ((seed || 0) % TWO_PI) / TWO_PI;          // 0..1 around the border
    const pad = 26 + Math.min(s.w, s.h) * 0.02;
    const hw = s.w / 2 + pad, hh = s.h / 2 + pad;
    const per = 2 * (hw * 2 + hh * 2), d = p * per;
    let t = d;
    if (t < hw * 2) return { x: s.x - hw + t, y: s.y - hh };
    t -= hw * 2;
    if (t < hh * 2) return { x: s.x + hw, y: s.y - hh + t };
    t -= hh * 2;
    if (t < hw * 2) return { x: s.x + hw - t, y: s.y + hh };
    t -= hw * 2;
    return { x: s.x - hw, y: s.y + hh - t };
}
// The nearest site in this sector still wanting work, or null. Far-off sites
// are left alone so a citizen across the map keeps wandering instead of
// striking out on a thousand-unit march.
function nearestBuildSite(x, y, maxD) {
    let best = null, bestD = Infinity;
    for (const s of buildSites) {
        if (s.done || s.level !== currentLevel) continue;
        // Measured against the site's own size: a fixed radius would have a
        // crew member standing at one end of a hundred-metre slab decide the
        // job it is leaning on is too far away to walk to.
        const reach = (maxD || 1100) + Math.max(s.w, s.h) * 0.5;
        const d = dist(x, y, s.x, s.y);
        if (d < reach && d < bestD) { bestD = d; best = s; }
    }
    return best;
}

// --- the crew: who hammers, who hauls, and who works with whom ------------
//
// Run once a frame for the whole sector rather than per citizen, because the
// split and the pairing are properties of the crew as a group and a citizen
// deciding on its own would flip roles every time the roster changed.
//
// Roles alternate down a stable roster, so it is half and half (haulers take
// the odd one, which is what makes the doubling-up case below reachable at all).
// Pairing is then round-robin: hauler k works with hammer k % hammers. That is
// the round-robin form of "find the next unpaired mason" -- with equal numbers
// every mason gets exactly one hauler, and a mason only ever sees a second one
// when there are more haulers than masons, i.e. when the crew is odd. It is
// also stable frame to frame, which a search is not.
const BUILD_HAUL_LOAD = 46;      // frames spent reaching into the container
const BUILD_HANDOFF   = 30;      // frames the two of them spend on the exchange
const BUILD_PLACE     = 54;      // frames the mason spends setting the material

function updateBuildCrews() {
    if (typeof townCitizens === 'undefined' || !townCitizens.length) return;
    const live = [];
    for (const s of buildSites) {
        if (s.done || s.level !== currentLevel) continue;
        s.__crew = [];
        live.push(s);
    }
    if (!live.length) {
        for (const c of townCitizens) {
            if (c.role !== "ARCHITECTURE") continue;
            c.buildSite = null; c.pairMason = null; c.carrying = null;
        }
        return;
    }
    for (const c of townCitizens) {
        if (c.role !== "ARCHITECTURE") continue;
        const s = nearestBuildSite(c.x, c.y);
        c.buildSite = s;
        if (s) s.__crew.push(c);
        else { c.pairMason = null; c.carrying = null; }
    }
    for (const s of live) {
        const crew = s.__crew;
        // Stable order, so the split does not reshuffle as people walk about.
        crew.sort((a, b) => a.slotSeed - b.slotSeed);
        const masons = [], haulers = [];
        for (let i = 0; i < crew.length; i++) {
            const c = crew[i];
            c.buildRole = (i % 2 === 0) ? "HAUL" : "HAMMER";
            (c.buildRole === "HAUL" ? haulers : masons).push(c);
        }
        // One mason and nobody to fetch for them still works -- they hammer.
        // One hauler and no mason has nowhere to carry to, so they hammer too.
        if (!masons.length) { for (const c of crew) { c.buildRole = "HAMMER"; c.carrying = null; c.pairMason = null; } continue; }
        for (const m of masons) m.haulerCount = 0;
        for (let k = 0; k < haulers.length; k++) {
            const m = masons[k % masons.length];
            haulers[k].pairMason = m;
            m.haulerCount++;
        }
    }
}

// --- the ghost, in world space, drawn over everything ---------------------
function drawBuildGhost() {
    if (!buildGhost) return;
    const g = buildGhost;
    const c = g.ok ? [90, 170, 255] : [235, 70, 60];
    push(); translate(g.x, g.y);
    noStroke(); fill(c[0], c[1], c[2], 34);
    rect(-g.w / 2, -g.h / 2, g.w, g.h, 4);
    // Corner ticks rather than a full box: the outline stays readable over
    // busy ground, and the corners are what the player is actually aligning.
    stroke(c[0], c[1], c[2], 235); strokeWeight(3); noFill();
    const t = Math.min(34, Math.min(g.w, g.h) * 0.3), hw = g.w / 2, hh = g.h / 2;
    for (const sx of [-1, 1]) for (const sy of [-1, 1]) {
        line(sx * hw, sy * hh, sx * (hw - t), sy * hh);
        line(sx * hw, sy * hh, sx * hw, sy * (hh - t));
    }
    strokeWeight(1.5); stroke(c[0], c[1], c[2], 110);
    rect(-hw, -hh, g.w, g.h);
    // A line back to the player, so it is obvious what is carrying the ghost.
    stroke(c[0], c[1], c[2], 90); strokeWeight(2);
    line(0, 0, player.x - g.x, player.y - g.y);
    noStroke();
    pop();
}

// --- the site and the finished structures ---------------------------------
function drawBuildSite(b) {
    const s = b.site, p = s ? s.progress : 0;
    const hw = b.w / 2, hh = b.h / 2;
    // Everything is a fraction of the footprint, so the same code reads as a
    // hoarded lot at 200 units across and at 2000. `u` is the detail unit --
    // the width of a scaffold pole, near enough -- and it never gets so small
    // that a line disappears or so large that it swallows the slab.
    const u = Math.max(3, Math.min(b.w, b.h) * 0.018);
    push(); translate(b.x, b.y);
    noStroke();
    fill(118, 110, 98); rect(-hw, -hh, b.w, b.h, u);                    // graded pad
    fill(150, 144, 132, 190);
    rect(-hw + u * 2.5, -hh + u * 2.5, b.w - u * 5, b.h - u * 5, u);    // poured slab
    // The frame goes up course by course, so the site reads its own progress
    // from across the street without a number on it.
    const rows = Math.max(1, Math.round(p * 5));
    stroke(126, 96, 58); strokeWeight(u * 1.5);
    for (let i = 0; i < rows; i++) {
        const inset = u * (3.2 + i * 1.1);
        noFill(); rect(-hw + inset, -hh + inset, b.w - inset * 2, b.h - inset * 2);
    }
    // Scaffold standards all round, not only on the corners: at this size four
    // poles on a hundred-metre slab read as four specks.
    noStroke(); fill(178, 150, 62);
    const px = Math.max(2, Math.round(b.w / (u * 26))), py = Math.max(2, Math.round(b.h / (u * 26)));
    for (let i = 0; i <= px; i++) for (const sy of [-1, 1]) {
        rect(-hw + u * 4 + ((b.w - u * 8) * i) / px - u, sy * (hh - u * 4) - u, u * 2, u * 2, u * 0.3);
    }
    for (let j = 1; j < py; j++) for (const sx of [-1, 1]) {
        rect(sx * (hw - u * 4) - u, -hh + u * 4 + ((b.h - u * 8) * j) / py - u, u * 2, u * 2, u * 0.3);
    }
    // Materials drop and a spoil heap by the site gate.
    fill(96, 78, 52); rect(-hw + u * 5, hh - u * 10, u * 13, u * 4.5, u * 0.5);
    fill(120, 100, 68); rect(-hw + u * 6.4, hh - u * 11.4, u * 13, u * 4.5, u * 0.5);
    fill(104, 96, 84); ellipse(-hw + u * 26, hh - u * 9, u * 14, u * 8);
    // Hoarding tape all round, dash count scaled so it stays a dashed line.
    stroke(226, 176, 40); strokeWeight(Math.max(2, u * 0.7));
    const dashes = Math.max(6, Math.min(40, Math.round(b.w / (u * 8))));
    for (let i = 0; i < dashes; i++) {
        const x0 = -hw + (b.w * i) / dashes, x1 = x0 + b.w / (dashes * 2);
        line(x0, -hh, x1, -hh); line(x0, hh, x1, hh);
    }
    noStroke();
    // Progress readout, near only. Sized off the footprint so it stays legible
    // at the zoom the structure forces.
    if (player && dist(player.x, player.y, b.x, b.y) < 520 + Math.max(b.w, b.h) * 0.6) {
        const bw = Math.min(b.w * 0.4, 260), bh = Math.max(10, u * 3);
        fill(0, 170); rect(-bw / 2 - u, -hh - bh - u * 3, bw + u * 2, bh + u * 2, u);
        fill(90, 170, 255); rect(-bw / 2, -hh - bh - u * 2, bw * p, bh, u * 0.6);
        fill(235); textAlign(CENTER, CENTER); textSize(Math.max(11, u * 3.4)); textFont('sans-serif');
        text(Math.floor(p * 100) + "%", 0, -hh - bh - u * 7);
    }
    pop();
}

// The materials lorry: flat-nosed cab at the east end, square container barrel
// behind it. Drawn nose-east because that is the axis truckSlot() hands the
// crew their three approaches on -- both flanks and the tailgate.
function drawSupplyTruck(b) {
    const hw = b.w / 2, hh = b.h / 2;
    const cabW = b.w * 0.30, conW = b.w * 0.62;
    push(); translate(b.x, b.y);
    noStroke();
    // Wheels first, so the body sits on them.
    fill(28, 26, 26);
    for (const wx of [hw - cabW * 0.68, -hw + conW * 0.22, -hw + conW * 0.72]) {
        rect(wx - 11, -hh - 3, 22, 10, 3); rect(wx - 11, hh - 7, 22, 10, 3);
    }
    // Chassis rail running the length.
    fill(52, 50, 50); rect(-hw + 4, -hh + 14, b.w - 8, b.h - 28, 3);
    // Container: ribbed square barrel with a hatch on the roof and a tailgate.
    fill(122, 118, 108); rect(-hw, -hh + 8, conW, b.h - 16, 5);
    fill(146, 142, 130); rect(-hw + 5, -hh + 13, conW - 10, b.h - 26, 3);
    stroke(104, 100, 92); strokeWeight(2);
    for (let i = 1; i < 6; i++) {
        const x = -hw + (conW * i) / 6;
        line(x, -hh + 12, x, hh - 12);
    }
    noStroke();
    fill(96, 92, 86); rect(-hw + conW * 0.30, -18, conW * 0.40, 36, 4);   // roof hatch
    fill(168, 164, 152); rect(-hw + conW * 0.34, -14, conW * 0.32, 8, 2);
    fill(74, 70, 64); rect(-hw - 3, -hh + 12, 7, b.h - 24, 2);            // tailgate
    fill(196, 150, 44); rect(-hw - 3, -4, 7, 8, 1);                        // catch
    // Cab.
    fill(178, 76, 44); rect(hw - cabW, -hh + 6, cabW, b.h - 12, 5);
    fill(202, 92, 56); rect(hw - cabW + 4, -hh + 10, cabW - 8, b.h - 20, 3);
    fill(70, 96, 118, 220); rect(hw - 14, -hh + 14, 10, b.h - 28, 2);     // windscreen
    fill(40, 38, 38); rect(hw - cabW - 5, -hh + 16, 6, b.h - 32, 2);      // back of the cab
    fill(226, 222, 208); ellipse(hw - 3, -hh + 20, 7, 7);                 // lamps
    ellipse(hw - 3, hh - 20, 7, 7);
    pop();
}

function drawBuiltStructure(b) {
    const hw = b.w / 2, hh = b.h / 2;
    // Same rule as the site: proportions, not absolute units. `u` is the trim
    // width, and every count below is clamped so a corrugated roof stays a
    // corrugated roof rather than becoming either two ribs or four hundred.
    const u = Math.max(3, Math.min(b.w, b.h) * 0.018);
    const span = (n, lo, hi) => Math.max(lo, Math.min(hi, Math.round(n)));
    push(); translate(b.x, b.y);
    noStroke();
    if (b.kind === "WAREHOUSE") {
        fill(96, 104, 112); rect(-hw, -hh, b.w, b.h, u);                       // shell
        fill(122, 130, 138); rect(-hw + u * 2, -hh + u * 2, b.w - u * 4, b.h - u * 4, u * 0.6);
        // Corrugation, then saw-tooth glazing running the length of the roof.
        stroke(88, 96, 104); strokeWeight(Math.max(1.5, u * 0.5));
        const ribs = span(b.w / (u * 5), 12, 44);
        for (let i = 1; i < ribs; i++) {
            const x = -hw + u * 4 + ((b.w - u * 8) * i) / ribs;
            line(x, -hh + u * 3, x, hh - u * 3);
        }
        noStroke();
        fill(150, 160, 170, 165);
        const bands = span(b.h / (u * 26), 2, 5);
        for (let j = 0; j < bands; j++) {
            const y = -hh + (b.h * (j + 0.5)) / bands;
            rect(-hw + u * 10, y - u * 2.2, b.w - u * 20, u * 4.4, u * 0.6);
        }
        // Loading bays down the west face, with an apron they open onto.
        fill(78, 74, 68); rect(-hw - u * 7, -hh + u * 6, u * 7, b.h - u * 12, u * 0.4);
        const bays = span(b.h / (u * 18), 2, 6);
        for (let j = 0; j < bays; j++) {
            const y = -hh + (b.h * (j + 0.5)) / bays;
            fill(58, 62, 68); rect(-hw, y - u * 5, u * 4, u * 10, u * 0.5);
            fill(196, 150, 44); rect(-hw, y - u * 5, u * 4, u * 1.6, u * 0.3);
        }
    } else if (b.kind === "LABORATORY") {
        fill(206, 210, 214); rect(-hw, -hh, b.w, b.h, u * 1.4);
        fill(228, 232, 236); rect(-hw + u * 2.4, -hh + u * 2.4, b.w - u * 4.8, b.h - u * 4.8, u);
        // Glazed atrium across the middle, mullions at a readable pitch.
        fill(96, 160, 190, 200); rect(-hw + u * 6, -u * 4.5, b.w - u * 12, u * 9, u * 0.6);
        stroke(226, 232, 236); strokeWeight(Math.max(1.5, u * 0.45));
        const mull = span(b.w / (u * 9), 6, 26);
        for (let i = 1; i < mull; i++) {
            const x = -hw + u * 6 + ((b.w - u * 12) * i) / mull;
            line(x, -u * 4.5, x, u * 4.5);
        }
        noStroke();
        // Roof plant: chiller decks along both flanks.
        const decks = span(b.h / (u * 30), 2, 5);
        for (let j = 0; j < decks; j++) {
            const y = -hh + (b.h * (j + 0.5)) / decks;
            if (Math.abs(y) < u * 8) continue;                                 // clear of the atrium
            fill(150, 158, 166); rect(hw - u * 17, y - u * 5, u * 12, u * 10, u * 0.6);
            fill(180, 188, 196); rect(hw - u * 15.5, y - u * 3.6, u * 9, u * 7.2, u * 0.4);
            fill(150, 158, 166); rect(-hw + u * 5, y - u * 4, u * 9, u * 8, u * 0.6);
        }
        fill(70, 130, 170); rect(-hw - u * 3, -u * 7, u * 3.4, u * 14, u * 0.6); // entry
    } else if (b.kind === "RANGE") {
        fill(132, 122, 104); rect(-hw, -hh, b.w, b.h, u);                      // gravel apron
        fill(112, 104, 88); rect(-hw + u * 3, -hh + u * 3, b.w - u * 6, b.h - u * 6, u * 0.6);
        // Earth backstop across the east end, crest catching the light.
        fill(88, 74, 52); rect(hw - u * 11, -hh + u * 2, u * 10, b.h - u * 4, u);
        fill(104, 88, 62); rect(hw - u * 9.6, -hh + u * 4, u * 7, b.h - u * 8, u * 0.6);
        fill(124, 106, 76); rect(hw - u * 8.4, -hh + u * 5, u * 3, b.h - u * 10, u * 0.4);
        // Six lanes, whatever the footprint: the count is the design, not the
        // spacing, so they stay lanes rather than becoming hatching.
        const lanes = 6;
        stroke(150, 142, 126); strokeWeight(Math.max(1.5, u * 0.6));
        for (let j = 1; j < lanes; j++) {
            const y = -hh + u * 5 + ((b.h - u * 10) * j) / lanes;
            line(-hw + u * 12, y, hw - u * 12, y);
        }
        noStroke();
        for (let j = 0; j < lanes; j++) {
            const y = -hh + u * 5 + ((b.h - u * 10) * (j + 0.5)) / lanes;
            fill(226, 226, 220); rect(hw - u * 14, y - u * 2.6, u * 2.2, u * 5.2, u * 0.3);
            fill(190, 60, 50); ellipse(hw - u * 12.9, y, u * 1.6, u * 1.6);
            fill(74, 70, 64); rect(-hw + u * 7, y - u * 2, u * 5, u * 4, u * 0.4);  // benches
        }
        fill(64, 60, 54); rect(-hw + u * 2.5, -hh + u * 3, u * 4, b.h - u * 6, u * 0.5);  // firing line
        fill(196, 60, 50); rect(-hw + u * 3, -u * 3, u * 3, u * 6, u * 0.3);
    } else if (b.kind === "FARM") {
        fill(146, 44, 38); rect(-hw, -hh, b.w, b.h, u);                        // barn
        fill(172, 58, 48); rect(-hw + u * 1.8, -hh + u * 1.8, b.w - u * 3.6, b.h - u * 3.6, u * 0.6);
        // Gambrel read from above: ridge down the spine with a shaded plane
        // either side, so it is a roof rather than a red rectangle.
        fill(158, 50, 42); rect(-hw + u * 1.8, -u * 7, b.w - u * 3.6, u * 14);
        fill(120, 34, 30); rect(-u * 2.2, -hh + u * 1.8, u * 4.4, b.h - u * 3.6);
        stroke(226, 220, 208); strokeWeight(Math.max(2, u));                    // trim
        noFill(); rect(-hw + u * 1.8, -hh + u * 1.8, b.w - u * 3.6, b.h - u * 3.6, u * 0.6);
        noStroke();
        fill(226, 220, 208);                                                    // big doors
        rect(-hw - u * 1.2, -u * 9, u * 3.4, u * 18, u * 0.4);
        fill(120, 34, 30); rect(-hw - u * 1.2, -u * 0.7, u * 3.4, u * 1.4);
        fill(206, 176, 92); rect(hw - u * 8, -u * 4, u * 6, u * 8, u * 0.6);     // hay door
        // Cupolas along the ridge -- the tell that says barn from a distance.
        const cup = span(b.w / (u * 34), 2, 5);
        for (let i = 0; i < cup; i++) {
            const x = -hw + (b.w * (i + 0.5)) / cup;
            fill(226, 220, 208); rect(x - u * 2, -u * 2, u * 4, u * 4, u * 0.4);
            fill(120, 34, 30); rect(x - u * 1.2, -u * 1.2, u * 2.4, u * 2.4, u * 0.3);
        }
    }
    pop();
}

// --- the placement HUD, screen space --------------------------------------
function drawBuildHud() {
    if (!buildGhost) return;
    const bw = 150, bh = 46, y = height - 150;
    const okCol = buildGhost.ok ? [40, 120, 200] : [70, 70, 70];
    push(); textAlign(CENTER, CENTER); textFont('sans-serif');
    fill(0, 150); noStroke(); rect(width / 2 - 210, y - 76, 420, 44, 8);
    fill(235); textSize(15);
    const bp = BLUEPRINTS[buildGhost.kind];
    const eta = buildEtaDays(1);
    text((bp ? bp.label : buildGhost.kind) + "  -  " +
         (buildCrew() > 0 ? (eta < 1 ? "under a day" : Math.ceil(eta) + " day" + (Math.ceil(eta) > 1 ? "s" : ""))
                          : "NO CREW ASSIGNED"), width / 2, y - 54);

    fill(okCol[0], okCol[1], okCol[2], 220);
    stroke(buildGhost.ok ? color(120, 200, 255) : color(120)); strokeWeight(2);
    rect(width / 2 - 160, y, bw, bh, 8);
    fill(120, 40, 40, 220); stroke(220, 120, 120); rect(width / 2 + 10, y, bw, bh, 8);
    noStroke(); fill(255); textSize(18);
    text(buildGhost.ok ? "PLACE" : "BLOCKED", width / 2 - 160 + bw / 2, y + bh / 2);
    text("CANCEL", width / 2 + 10 + bw / 2, y + bh / 2);
    pop();
}
// Returns true if the tap was the placement HUD's, so the caller stops there.
function handleBuildHudTap(mx, my) {
    if (!buildGhost) return false;
    const bw = 150, bh = 46, y = height - 150;
    if (my < y || my > y + bh) return false;
    if (mx > width / 2 - 160 && mx < width / 2 - 160 + bw) { confirmBuildPlacement(); return true; }
    if (mx > width / 2 + 10 && mx < width / 2 + 10 + bw) { cancelBuildPlacement(); return true; }
    return false;
}
function updateProductionMeters() {
    if (window.farmLvl === undefined) {
        window.farmXP = 0; window.milXP = 0; window.sciXP = 0; window.archXP = 0;
        window.farmLvl = 1; window.milLvl = 1; window.sciLvl = 1; window.archLvl = 1;
        window.archBarrierReady = false;
    }
    if (currentLevel < 1 || isDead || isWin || isPaused || inTownCutscene || inWorldBuildingMenu) return;

    // Accrue against the world clock, not the frame counter.
    //
    // This used to tick on `frameCount % 60`, which is only "once a second" if
    // the game is holding 60 fps -- at 30 it paid out half as fast, so how
    // quickly a settlement developed depended on the player's phone. It now
    // shares the same millisecond delta the sun runs on, so a second of
    // production is a second of production everywhere, and the two systems can
    // never disagree about how much time has passed.
    window.__meterAcc = (window.__meterAcc || 0) + worldClockDtMs;
    if (window.__meterAcc >= 1000) {
        const secs = Math.min(5, Math.floor(window.__meterAcc / 1000));
        window.__meterAcc -= secs * 1000;
        // Force them to be numbers so the math never breaks
        let pF = Number(popFarming) || 0;
        let pM = Number(popMilitary) || 0;
        let pS = Number(popScience) || 0;
        let pA = Number(popArchitecture) || 0;

        // Multiplied by 0.001 to dramatically slow down the leveling speed
        let fRate = (pF * (1 + Math.min(5, Math.floor(pF / 10)) * 0.1)) * 0.001;
        let milActive = Math.max(0, pM - ((Number(window.militaryToBringM) || 0) + (Number(window.militaryToBringF) || 0)));
        let mRate = (milActive * (1 + Math.min(5, Math.floor(milActive / 10)) * 0.1)) * 0.001;
        let sRate = (pS * (1 + Math.min(5, Math.floor(pS / 10)) * 0.1)) * 0.001;
        let aRate = (pA * (1 + Math.min(5, Math.floor(pA / 10)) * 0.1)) * 0.001;

        window.farmXP += fRate * secs; window.milXP += mRate * secs;
        window.sciXP  += sRate * secs; window.archXP += aRate * secs;
        checkLevelUps();
    }
}
function triggerLvl4Ambush() {
    nm0AmbushActive = true;
    nm0AmbushKills = 150; 
    window.ambushSpawnsRemaining = 100;
    objectiveTimer = 360;
    streakMsgText = "NM-0 GREY FATIGUE AMBUSH!";
    streakMsgTimer = 120;

    // First initial wave spawn
    for(let i = 0; i < 50; i++) {
        let sX = random() > 0.5 ? -1500 : 1500; 
        let sY = player.y + random(-1000, 1000);
        let e = new Character(sX, sY, false, "NM0_GREY_FATIGUE");
        e.state = "CHASE"; 
        e.loseSightTimer = 2500;
        e.isAmbush = true;
        enemiesList.push(e);
    }
}


// ############################################################################
// ##                                                                        ##
// ##   OPEN-WORLD BIOME ENGINE  —  chunk streaming, travel, terrain art     ##
// ##                                                                        ##
// ##   Biomes 1-7 are standalone infinite worlds. Level 0 (prologue) and    ##
// ##   Level 8 (NM-0 HQ interior) are untouched hand-authored maps.         ##
// ##                                                                        ##
// ############################################################################

const CHUNK_W        = 1200;   // world units per chunk edge (= 1 city block + streets)
// Baked terrain buffer. At 320 this was 3.75 world units per texel, and the
// blit magnified it 3.75x with nearest-neighbour filtering: every texel edge
// snapped to a different screen pixel as the camera panned, so the whole ground
// crawled and strobed while you walked. 384 puts it at 3.125 units per texel,
// and the blit now filters (see ChunkManager.drawTerrain). The cache below is
// cut to match so the memory footprint is unchanged.
const CHUNK_TEX      = 384;
const CHUNK_BASE     = 200;    // resolution of the per-pixel noise pass only
const CHUNK_LOAD_R   = 2;      // chunks loaded in each direction -> 5x5 = 25 live
const CHUNK_KEEP_R   = 3;      // evict beyond this ring
// Terrain bakes are amortised across frames so a residency change never costs
// one long hitch. The old cap was a flat 1 per frame, which meant a full ring
// took 25 frames to resolve and every one of those frames drew flat fill where
// the detail had not landed yet -- the strobing. A short wall-clock budget
// spends whatever slack the frame has instead, and the visible chunks are
// exempt from it entirely (see ChunkManager.ensureVisibleBaked).
const CHUNK_BAKE_CAP = 4;      // max terrain bakes per frame
const CHUNK_BAKE_MS  = 7;      // ...or until this much of the frame is gone
const CHUNK_TEX_CACHE = 14;    // retired terrain buffers kept for backtracking
const NOISE_GRID     = 4;      // noise sampled every Nth pixel, then interpolated
const BIOME_SEED     = 1337;

let BIOME_ACTIVE = false;      // true while inside a streamed biome

