      g.rect(-7 * s, -1.6 * s, 14 * s, 3.2 * s, 1.5);
      g.ellipse(-7 * s, 0, 4.5 * s, 4.5 * s);
      g.ellipse(7 * s, 0, 4.5 * s, 4.5 * s);
